#!/usr/bin/env python3
"""
gen_audio_samples.py
Generate 35 interview-answer WAV files using OpenAI tts-1 (cheapest model).
Each ~1 minute of speech. Stored in load_tests/audio_samples/.

Usage:
    python load_tests/gen_audio_samples.py
"""
import os, sys, random, time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent))
from dotenv import load_dotenv
load_dotenv(Path(__file__).parent.parent / ".env", override=True)

from openai import OpenAI

client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"), timeout=60.0, max_retries=1)

OUT_DIR = Path(__file__).parent / "audio_samples"
OUT_DIR.mkdir(exist_ok=True)

# 6 voices — rotate for variety
VOICES = ["alloy", "echo", "fable", "onyx", "nova", "shimmer"]

# 35 realistic interview answers (~130-160 words each → ~55-65s at 130wpm)
ANSWERS = [
    # ── Leadership ──────────────────────────────────────────────────────
    """In my previous role as a senior engineer I led a team of eight developers through a critical product migration. The biggest challenge was aligning everyone on priorities when we had competing deadlines from three different stakeholders. I introduced a weekly alignment meeting where each stakeholder ranked their top three requirements. This created transparency and reduced last-minute scope changes by about sixty percent. I also implemented a buddy system pairing senior and junior engineers so knowledge transfer happened organically. By the end of the quarter we shipped the migration two weeks ahead of schedule with zero production incidents. The key lesson I took away was that clear communication structures matter more than technical decisions in most cross-functional projects. I still apply that framework today whenever I join a new team or start a new initiative.""",

    """When I took over the product team the roadmap had over two hundred open feature requests and no clear prioritisation framework. My first step was to run a discovery workshop with our top twenty customers to understand which pain points were costing them actual time or money. From that we distilled fifteen high-impact themes. I then scored each theme across three dimensions: customer value, strategic alignment, and engineering effort. This gave us a prioritised backlog that every stakeholder could see and understand. Within six months we shipped four of the top five themes and customer satisfaction scores improved by twenty-two points. The process taught me that good product strategy is really about making explicit trade-offs visible to everyone, not just the product team.""",

    """One of the most difficult leadership moments I faced was having to let go of a high-performing individual who was creating a toxic dynamic on the team. Despite their technical output being excellent their behaviour was causing two other engineers to consider leaving. I had multiple one-on-one conversations, set clear behavioural expectations, and gave a formal performance improvement plan. When the behaviour did not change I had to make the call to part ways. Within a month team morale visibly improved and one of the engineers who had been considering leaving told me they felt safe to speak up again. It reinforced for me that team health is a product metric just as much as velocity or quality.""",

    """During a major outage that lasted four hours I was the incident commander coordinating across six teams simultaneously. My approach was to keep a running shared document visible to everyone showing what we had tried and what was still unknown. I assigned one person per team as a single point of contact so I was not getting flooded with messages. We identified the root cause as a misconfigured database connection pool that was introduced in a routine deployment. After restoring service I ran a blameless post-mortem the next day. We introduced automated connection pool validation to our CI pipeline and the same failure mode has not recurred in the eighteen months since. The experience fundamentally changed how I think about on-call rotations and runbook quality.""",

    """I built a mentorship programme from scratch at my last company because I noticed junior engineers were leaving within their first year at a higher rate than senior ones. I surveyed the junior cohort and found that most felt they lacked a clear growth path. I designed a structured six-month mentorship pairing each junior with a senior, with monthly check-ins and a shared growth document. Participation was voluntary but within two cycles we had seventy percent of the engineering org enrolled. The one-year retention rate for junior engineers improved from fifty-five percent to eighty-one percent. I also saw unexpected benefits: senior engineers reported feeling more engaged because mentoring gave them a different kind of challenge beyond their technical work.""",

    # ── Product & Strategy ───────────────────────────────────────────────
    """When I was tasked with growing our enterprise segment I started by deeply analysing our existing enterprise customers to understand what made them successful with our product. I found three common patterns: they all had a dedicated internal champion, they had integrated our API with at least one other internal tool, and they had gone through a structured onboarding in the first thirty days. I used those findings to redesign our enterprise onboarding programme around those three pillars. We assigned dedicated success managers to new enterprise accounts, created integration playbooks for the top five tools our customers used, and built a thirty-day checklist. Within two quarters enterprise churn dropped from eighteen percent annually to nine percent. It was a great example of letting data from existing customers guide acquisition and retention strategy simultaneously.""",

    """I led the zero-to-one launch of a developer tool that had no existing market benchmark. Rather than doing traditional market sizing I ran a series of twenty customer discovery interviews with engineers at companies of different sizes. I was looking for the specific moment they felt the pain we were solving. Almost universally they described it as happening during code review when integration bugs slipped through. That insight shaped everything from our positioning to our feature prioritisation. We launched a beta with forty companies, iterated based on feedback over three months, and hit general availability with a product that already had strong word-of-mouth in developer communities. In the first six months we reached ten thousand active developers without paid acquisition, purely through community and content.""",

    """The most complex go-to-market decision I have made was choosing between a product-led and a sales-led motion for our mid-market expansion. The data showed that product-led trials converted at higher rates but had a longer time-to-value. Sales-led deals closed faster but required more support resources. I proposed a hybrid model: product-led for companies under five hundred employees and a light-touch sales-assisted model for larger ones. We built a scoring system that automatically routed trials to the right track based on company size and usage signals. After six months the hybrid model outperformed both pure motions in terms of revenue per sales dollar spent. The key was not picking one motion but understanding where each worked best and building the infrastructure to support both.""",

    """I once had to kill a feature that had taken three months to build because the data showed it was not driving the outcomes we had predicted. The feature had strong internal advocates and the team was proud of the work. I presented the usage data, the retention impact, and a hypothesis about why adoption was low. I framed the decision as a learning, not a failure, and proposed redirecting the engineering capacity toward the next highest-priority item on the roadmap. The conversation was uncomfortable but honest. Looking back, making that call quickly prevented us from investing further in a dead end and freed up resources that ultimately shipped one of our most successful features. It reinforced the importance of setting clear success metrics before building anything.""",

    """When we noticed that our mobile retention numbers were significantly lower than desktop I initiated a deep-dive investigation. I shadowed five mobile users doing screen recordings, analysed drop-off funnels, and ran a survey. The finding was that the mobile onboarding flow had six steps compared to three on desktop, and users were abandoning at step four. We simplified the mobile onboarding, used progressive disclosure to defer non-critical steps, and reduced time-to-first-value from eleven minutes to three. Mobile day-thirty retention improved from twenty-two percent to thirty-eight percent over the next quarter. The lesson was that the same product on different surfaces often needs fundamentally different interaction design, not just a resized layout.""",

    # ── Technical ────────────────────────────────────────────────────────
    """I designed and implemented a distributed task queue to replace our legacy cron-based system that was causing race conditions under high load. The core challenge was ensuring exactly-once execution semantics across multiple worker nodes. I chose to use a database-backed queue with optimistic locking rather than a message broker because our consistency requirements were strict and we wanted to avoid the operational overhead of managing a separate broker cluster. I implemented exponential backoff with jitter for retries, dead letter handling, and a monitoring dashboard showing queue depth and worker health. After the migration our task failure rate dropped from two percent to less than zero point one percent and we eliminated the race conditions entirely. The system now processes four million tasks per day reliably.""",

    """One of the most interesting technical problems I solved was reducing the p99 latency of our search API from eight hundred milliseconds to under one hundred milliseconds. I started by profiling production traces and found that sixty percent of the latency was coming from a single database query that was doing a full-table scan on a million-row table. I added a composite index, rewrote the query to use covering indexes, and introduced a read replica for search traffic. I also added a Redis cache with a five-minute TTL for the top ten percent of queries by frequency. The combined changes brought p99 down to eighty milliseconds. The exercise reinforced that performance optimisation almost always starts with measurement, not assumptions.""",

    """I architected a real-time data pipeline that processed over one hundred thousand events per second with end-to-end latency under two seconds. The design used Kafka as the event bus, Flink for stream processing, and Elasticsearch for the queryable store. The trickiest part was handling late-arriving events caused by mobile clients with intermittent connectivity. I implemented a watermark strategy with a five-minute grace window and idempotent event processing using a composite key of device ID and sequence number. The pipeline ran in production for two years without a single data loss incident. When I left the team it was processing over two hundred thousand events per second with no architectural changes needed, just horizontal scaling of the Kafka partitions and Flink job parallelism.""",

    """I led the migration of a monolithic Rails application to a microservices architecture over eighteen months without any downtime for our customers. The strategy was the strangler fig pattern: we identified the highest-value boundaries first, extracted them as independent services, and used a feature flag system to gradually route traffic. The hardest part was shared data: services that previously joined across tables now needed their own data stores. We used the outbox pattern for event-driven data synchronisation between services. At the end of the migration we had reduced deployment cycle time from two weeks to twice daily and the teams owning individual services shipped features independently without coordinating releases. The biggest lesson was that organisational structure needs to evolve alongside the technical architecture or you get the worst of both worlds.""",

    """I built a machine learning pipeline for fraud detection that reduced false positives by forty percent while maintaining the same recall rate. The previous rule-based system was brittle and required constant manual tuning. I replaced it with a gradient boosted tree model trained on twelve months of transaction data with over two hundred engineered features. The key innovation was adding behavioural sequence features capturing patterns in the last ten transactions per user, which the rule-based system could not represent. I used SHAP values to make the model explainable to the compliance team, which was a requirement for regulatory approval. The model ran inference in under thirty milliseconds per transaction using a lightweight serving layer. Fraud losses dropped by twenty-eight percent in the quarter after deployment.""",

    # ── Behavioural ──────────────────────────────────────────────────────
    """The most stressful project I have managed was a regulatory compliance deadline that we discovered we were going to miss two weeks before the due date. I immediately convened a war room with engineering, legal, and product. We mapped every remaining requirement against our current state and identified three that were blockers. I negotiated scope on two of them with our legal team, finding equivalent implementations that were faster to build. For the third I pulled in two engineers from another team temporarily. We worked in focused two-day sprints with daily check-ins directly with the CTO. We hit the deadline with one day to spare. The experience taught me that in a crisis the most valuable thing a leader can do is create clarity: clear scope, clear owners, clear timeline.""",

    """A situation where I had to give difficult feedback was when a direct report was consistently missing project estimates by large margins. I prepared for the conversation by gathering specific examples with dates and the actual versus estimated durations. I opened by asking them to share their perspective on project planning first. It turned out they were consistently underestimating because they felt pressure to give aggressive timelines to appear fast. Once I understood the root cause we worked together on a new estimation framework using historical data and a built-in buffer for unknowns. Their estimation accuracy improved from about fifty percent to over eighty percent in the next quarter. The conversation changed our relationship positively because it showed them I was invested in their success, not their short-term output.""",

    """I was once asked to deliver a project in six weeks that realistically needed twelve. Rather than simply accepting the deadline or refusing I requested a meeting with the stakeholders to walk through the scope and constraints transparently. I built a dependency map showing which features could ship in six weeks and which could not. I proposed a phased release: a minimum viable version in six weeks covering the core use case, and the full feature set in ten weeks. The stakeholders agreed to the phased approach once they saw the trade-offs clearly. The first phase shipped on time, satisfied the immediate business need, and the full version followed four weeks later. The lesson was that negotiation on scope is almost always preferable to promising something you cannot deliver.""",

    """I once joined a team that was deeply demoralised after a failed product launch. The team had worked for six months on a feature that was pulled one week before release due to a strategic pivot. My first priority was listening: I held individual conversations with every team member to understand how they were feeling and what they needed. I then worked with leadership to get the team committed to a smaller, achievable project that could ship within four weeks. Having a visible win was critical to rebuilding confidence. I also advocated for a retrospective on the cancelled project so the team could close the chapter properly. Three months later the same team shipped one of the most successful launches of the year. Psychological safety and small wins are underrated recovery tools.""",

    """The time I most disagreed with a decision made above me was when leadership decided to deprioritise a critical infrastructure investment in favour of new feature development. I believed the technical debt would compound and create reliability issues within six months. I wrote a detailed memo outlining the risk with supporting data from our incident history and projected future impact on engineering velocity. I presented it to the VP of Engineering. While the decision was not reversed immediately leadership allocated one engineer to address the highest-risk items. When one of the predicted failures occurred three months later my memo was referenced and we got full resourcing for the infrastructure work. The experience reinforced that disagreement is most effective when it is data-driven, written down, and proposed as a specific alternative, not just a complaint.""",

    # ── Analytical & Problem Solving ─────────────────────────────────────
    """When our core signup conversion rate dropped by fifteen percent over two weeks with no corresponding product change I led the root cause investigation. I started by segmenting the drop by traffic source, device type, geography, and acquisition channel. The drop was concentrated entirely in organic search traffic on mobile devices. I then analysed the changes in that period: a Google search algorithm update had changed our landing page ranking for key terms, and simultaneously our page load time on mobile had increased from two point one seconds to three point eight seconds after a third-party script was added. Fixing the page load time by deferring the script brought conversion back to baseline within a week. The algorithm ranking recovered over the following month. The investigation reinforced the value of segmentation before jumping to conclusions.""",

    """I was given an ambiguous mandate to improve the efficiency of our customer support operations without cutting headcount. My first step was spending two days sitting with support agents to understand their workflows. I found that forty percent of their time was spent on five types of repetitive questions that could be answered by a self-service knowledge base. I also found that the internal tool they used required eight clicks to resolve a common issue type. I prioritised three initiatives: expanding the help centre content for those five question types, adding a chatbot to deflect simple queries, and reducing the common workflow from eight clicks to two. Six months later ticket volume per agent dropped by thirty percent and agent satisfaction scores improved because they were spending more time on genuinely complex problems.""",

    """I used A/B testing to resolve a heated internal debate about whether a simplified or detailed pricing page would convert better. One camp believed customers needed all the information upfront. The other believed simplicity reduced cognitive load and increased conversion. Rather than making the decision based on opinion I designed a rigorous experiment with equal traffic split, a two-week run time to account for day-of-week effects, and conversion to paid subscription as the primary metric. The simplified page won with statistical significance at ninety-five percent confidence, improving paid conversion by eleven percent. The process also shifted our culture toward testing before building because the team saw firsthand how often intuition is wrong. We now run over thirty experiments per quarter across the product.""",

    """When I inherited a data warehouse that was costing four times what it should I conducted a systematic audit of query patterns and storage usage. I found that eighty percent of query costs came from twenty percent of queries, most of which were running full-table scans on billion-row tables because engineers were not using partition pruning. I ran a workshop on query optimisation, added automated cost alerts for queries exceeding a threshold, and refactored the ten most expensive recurring queries. I also implemented a tiered storage policy moving data older than ninety days to cheaper cold storage. Within two months cloud data warehouse costs dropped by sixty-two percent with no reduction in analytical capability. The savings funded two additional data engineering headcount, creating a virtuous cycle.""",

    """I was tasked with evaluating whether to build or buy a key component of our platform. I structured the analysis across four dimensions: total cost of ownership over three years, time to value, customisation needs, and vendor risk. I interviewed five potential vendors, ran a proof of concept with the top two, and calculated the internal engineering cost of building an equivalent solution. The build option was faster to customise but the three-year TCO was two point four times higher than buying. The vendor with the better proof of concept results also had strong contractual protections around data portability. I recommended buying and the decision saved approximately eight months of engineering time that was redirected to differentiated product work. The framework I used for that analysis has since been adopted as our standard build-versus-buy template.""",

    # ── Collaboration & Communication ─────────────────────────────────────
    """I once had to align four different department heads who had conflicting views on the same project timeline. Rather than running separate conversations I convened a single working session with all four, opened with a shared statement of the business goal, and asked each person to articulate what success looked like from their department's perspective. Writing those definitions on a shared board revealed that two of the apparent conflicts were actually about different metrics, not different goals. Once we agreed on the common metric the scheduling conflicts resolved themselves. The project launched on the agreed date with all four departments satisfied. The lesson I took away is that conflicts over timelines are often really conflicts over undefined success criteria, and resolving the latter automatically resolves the former.""",

    """Working with a difficult stakeholder is something I have navigated multiple times. In one case a VP of Sales consistently bypassed the product roadmap process and went directly to engineers with feature requests. Instead of escalating I requested a recurring thirty-minute sync with the VP to understand their top three customer concerns each month. This gave them a formal channel, which reduced the ad-hoc interruptions to engineers. I also created a lightweight process for sales-driven requests to be triaged within forty-eight hours so they never felt ignored. Within two months the dynamic shifted from adversarial to collaborative. The VP became one of our strongest advocates in executive meetings for product investments. Sometimes the best way to manage a difficult stakeholder is to make them feel heard before they feel managed.""",

    """I led a cross-functional initiative that required coordinating legal, engineering, design, marketing, and customer success teams simultaneously. The biggest risk was dependencies: a delay in one team would cascade to others. I built a dependency graph at the start of the project and used it to identify the critical path. I ran a weekly fifteen-minute standup for all teams focused only on blockers and dependencies, not status updates which were captured asynchronously in a shared document. I also built in a two-week buffer before the external deadline that only I and the project sponsor knew about. When a legal review took longer than expected we absorbed the delay within the buffer and still shipped on time. Cross-functional projects succeed or fail based on dependency management more than any individual team's execution.""",

    """I presented a recommendation to the board of directors that was initially rejected and had to defend it under intense questioning. The recommendation was to delay a product launch by one quarter to address security vulnerabilities we had found in an audit. The board was concerned about competitive timing. I walked through the specific vulnerabilities, the potential regulatory and reputational consequences of a breach, and a quantified risk model showing that the expected cost of a breach was twelve times the cost of the delay. I also presented a communication plan for managing customer expectations during the delay. After forty-five minutes of questions the board approved the delay. The product launched in the following quarter with the security issues resolved and received no incidents. Presenting risk in financial terms rather than technical terms was the key to the decision.""",

    # ── Career & Growth ──────────────────────────────────────────────────
    """The skill I have worked hardest to develop in the last three years is executive communication. Early in my career I was comfortable presenting technical details to engineering peers but struggled to communicate the same ideas to non-technical leadership. I actively sought out opportunities to present at company all-hands meetings, volunteered to write the engineering section of board materials, and asked for feedback after every presentation. I also read extensively on storytelling frameworks for business contexts. The improvement was gradual but clear. Within two years I was regularly invited to present directly to the CEO and CFO on technical strategy. The biggest shift was learning to lead with the business implication and save the technical detail for follow-up questions rather than front-loading the explanation.""",

    """I made a significant career mistake early on when I over-rotated on individual technical output and neglected team dynamics. I was the highest-performing individual contributor on my team by most metrics but I was not sharing context, not documenting my work, and not mentoring others. When I took a two-week vacation the team hit multiple blockers because too much knowledge was in my head. My manager gave me direct feedback that being individually excellent at the cost of team effectiveness was not the kind of seniority the company needed. That feedback changed how I thought about my role completely. I started writing technical design documents, hosting knowledge-sharing sessions, and investing in my teammates' growth. Within a year my team's overall output exceeded my individual contribution, which felt far more meaningful.""",

    """The most important professional lesson I have learned is that the quality of your questions matters more than the quality of your answers. Early in my career I thought expertise meant having the answers. I have since learned that the best engineers and leaders I have worked with are characterised by the precision and depth of their questions. Good questions surface assumptions, reveal hidden constraints, and create alignment before work begins. I now start every new project with a structured set of questions: What does success look like in six months? What are the top three risks? What would make us kill this project? Who has the most to lose if this fails? These questions consistently reveal things that would have caused problems later. Curiosity, it turns out, is a better superpower than expertise.""",

    """I transitioned from a pure engineering role to a product management role mid-career and the biggest adjustment was shifting from solving problems to identifying the right problems to solve. In engineering I had clear inputs and clear criteria for success. In product the inputs were ambiguous and the criteria for success were often contested. I spent the first three months making the mistake of treating product decisions like engineering decisions: optimising for local clarity rather than systemic impact. The turning point was a conversation with a mentor who told me that a product manager's job is to hold uncertainty longer than everyone else, to resist premature closure, and to make decisions only when the cost of waiting exceeds the cost of being wrong. That reframe changed everything about how I approach my role.""",

    # ── Culture & Values ─────────────────────────────────────────────────
    """I built a culture of psychological safety on my team through consistent and deliberate actions over about eighteen months. I started by modelling vulnerability in our team meetings: sharing when I was uncertain, acknowledging mistakes publicly, and asking for help visibly. I made it a norm to celebrate learning from failures in our retrospectives, not just celebrating successes. I also introduced an anonymous question box before all-hands meetings so people who were not comfortable speaking up had an alternative channel. Over time team members started sharing concerns proactively rather than waiting for things to escalate. Our team's engagement scores increased by thirty points and attrition dropped to zero over that period. Safety is not a culture initiative; it is built through hundreds of small, consistent signals from leadership.""",

    """I introduced a practice of structured decision documentation on my team after we spent three hours in a meeting relitigating a decision we had made two months earlier. The format was simple: one page capturing the context, the options considered, the decision made, and the reasoning. We stored these in a shared wiki accessible to everyone. Within six months we had over forty decision records that new team members used to get context quickly, and recurring debates about old decisions dropped by ninety percent because we could just link to the record. The practice also improved the quality of decisions because knowing you were going to write it down forced clearer thinking before the meeting. It became one of the most valued team practices and has since spread to three other teams in the organisation.""",

    """I advocate strongly for inclusive hiring practices not just because it is the right thing to do but because I have seen directly how diverse teams produce better outcomes. On one team I managed we deliberately recruited candidates from non-traditional backgrounds including bootcamp graduates and career changers. Two of our best engineers came from those backgrounds. They brought different problem-solving approaches and were often the first to question assumptions that the rest of us took for granted. I standardised our interview process with structured questions and a scoring rubric to reduce interviewer bias. I also introduced a policy of always having at least two interviewers from different backgrounds for each candidate. Our team's diversity improved meaningfully and so did our product quality, particularly in areas where we needed to design for users very different from ourselves.""",
]

assert len(ANSWERS) == 36, f"Expected 36 answers, got {len(ANSWERS)}"

def generate_wav(text: str, voice: str, out_path: Path) -> None:
    response = client.audio.speech.create(
        model="tts-1",          # cheapest
        voice=voice,
        input=text,
        response_format="wav",  # direct WAV, no conversion needed
    )
    response.stream_to_file(str(out_path))

def main():
    print(f"Generating {len(ANSWERS)} WAV samples → {OUT_DIR}\n")
    total_chars = sum(len(a) for a in ANSWERS)
    # tts-1 pricing: $15 per 1M characters
    est_cost = total_chars / 1_000_000 * 15
    print(f"Estimated cost: ${est_cost:.4f} ({total_chars:,} chars)\n")

    for i, text in enumerate(ANSWERS):
        voice = VOICES[i % len(VOICES)]
        out_path = OUT_DIR / f"answer_{i+1:02d}_{voice}.wav"

        if out_path.exists():
            print(f"  [{i+1:02d}/35] ⏭  Already exists: {out_path.name}")
            continue

        print(f"  [{i+1:02d}/35] 🎙  {voice:8s} | {len(text):4d} chars → {out_path.name} ...", end="", flush=True)
        t0 = time.time()
        try:
            generate_wav(text, voice, out_path)
            size_kb = out_path.stat().st_size // 1024
            print(f" ✅ {time.time()-t0:.1f}s | {size_kb}KB")
        except Exception as e:
            print(f" ❌ {e}")
        time.sleep(0.3)   # gentle rate limiting

    generated = list(OUT_DIR.glob("*.wav"))
    print(f"\n✅ Done. {len(generated)} WAV files in {OUT_DIR}")
    total_mb = sum(f.stat().st_size for f in generated) / 1024 / 1024
    print(f"   Total size: {total_mb:.1f} MB")

if __name__ == "__main__":
    main()
